arguments.command:
curl -s -X POST https://slack.com/api/users.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" -d "limit=100" > /tmp/slack_users.json; python3 -c "
import json
d=json.load(open('/tmp/slack_users.json'))
for u in d.get('members',[]):
    print(u['id'], '|', u.get('real_name',''), '|', u.get('name',''))
print('---')
for u in d.get('members',[]):
    if 'priya' in (u.get('real_name','')+u.get('name','')).lower():
        print('PRIYA:', u['id'], u.get('real_name'), u.get('name'))
"

